import org.apache.commons.lang3.time.DateUtils;
import java.util.Calendar;
import java.util.GregorianCalendar;
import java.util.TimeZone;
import java.text.SimpleDateFormat;

public class Probe {
    public static void main(String[] args) throws Exception {
        System.out.println("Default TZ: " + TimeZone.getDefault());

        // SEMI_MONTH truncate
        Calendar c1 = Calendar.getInstance();
        c1.clear();
        c1.set(2002, Calendar.MARCH, 10, 13, 45, 1);
        c1.set(Calendar.MILLISECOND, 231);
        Calendar t1 = (Calendar) DateUtils.truncate(c1, DateUtils.SEMI_MONTH);
        System.out.println("truncate SEMI_MONTH day10: " + fmt(t1));

        Calendar c2 = Calendar.getInstance();
        c2.clear();
        c2.set(2002, Calendar.MARCH, 20, 13, 45, 1);
        c2.set(Calendar.MILLISECOND, 231);
        Calendar t2 = (Calendar) DateUtils.truncate(c2, DateUtils.SEMI_MONTH);
        System.out.println("truncate SEMI_MONTH day20: " + fmt(t2));

        // round SEMI_MONTH
        Calendar c3 = Calendar.getInstance();
        c3.clear();
        c3.set(2002, Calendar.MARCH, 10, 13, 45, 1);
        c3.set(Calendar.MILLISECOND, 231);
        Calendar r3 = (Calendar) DateUtils.round(c3, DateUtils.SEMI_MONTH);
        System.out.println("round SEMI_MONTH day10: " + fmt(r3));

        Calendar c4 = Calendar.getInstance();
        c4.clear();
        c4.set(2002, Calendar.MARCH, 1, 13, 45, 1);
        Calendar r4 = (Calendar) DateUtils.round(c4, DateUtils.SEMI_MONTH);
        System.out.println("round SEMI_MONTH day1: " + fmt(r4));

        // AM_PM ceiling
        Calendar c5 = Calendar.getInstance();
        c5.clear();
        c5.set(2002, Calendar.MARCH, 28, 5, 10, 0);
        Calendar r5 = (Calendar) DateUtils.ceiling(c5, Calendar.AM_PM);
        System.out.println("ceiling AM_PM hour5: " + fmt(r5));

        Calendar c6 = Calendar.getInstance();
        c6.clear();
        c6.set(2002, Calendar.MARCH, 28, 0, 0, 0);
        Calendar r6 = (Calendar) DateUtils.ceiling(c6, Calendar.AM_PM);
        System.out.println("ceiling AM_PM hour0: " + fmt(r6));

        // documented ceiling HOUR example
        Calendar c7 = Calendar.getInstance();
        c7.clear();
        c7.set(2002, Calendar.MARCH, 28, 13, 45, 1);
        c7.set(Calendar.MILLISECOND, 231);
        Calendar r7 = (Calendar) DateUtils.ceiling(c7, Calendar.HOUR_OF_DAY);
        System.out.println("ceiling HOUR_OF_DAY: " + fmt(r7));

        Calendar c8 = Calendar.getInstance();
        c8.clear();
        c8.set(2002, Calendar.MARCH, 28, 13, 45, 1);
        c8.set(Calendar.MILLISECOND, 231);
        Calendar r8 = (Calendar) DateUtils.ceiling(c8, Calendar.MONTH);
        System.out.println("ceiling MONTH: " + fmt(r8));

        // getFragmentInHours MONTH example
        Calendar c9 = Calendar.getInstance();
        c9.clear();
        c9.set(2008, Calendar.JANUARY, 6, 7, 15, 10);
        c9.set(Calendar.MILLISECOND, 538);
        System.out.println("getFragmentInHours MONTH: " + DateUtils.getFragmentInHours(c9, Calendar.MONTH));

        // getFragmentInSeconds DAY_OF_YEAR example
        System.out.println("getFragmentInSeconds DAY_OF_YEAR: " + DateUtils.getFragmentInSeconds(c9, Calendar.DAY_OF_YEAR));

        // parseDate lenient vs strict
        try {
            java.util.Date d = DateUtils.parseDate("February 942, 1996", "MMMM dd, yyyy");
            System.out.println("lenient parse ok: " + d);
        } catch (Exception e) {
            System.out.println("lenient parse failed: " + e);
        }
        try {
            java.util.Date d = DateUtils.parseDateStrictly("February 942, 1996", "MMMM dd, yyyy");
            System.out.println("strict parse ok: " + d);
        } catch (Exception e) {
            System.out.println("strict parse failed: " + e.getClass().getSimpleName());
        }

        // unsupported field
        try {
            DateUtils.truncate(Calendar.getInstance(), Calendar.DAY_OF_WEEK);
            System.out.println("DAY_OF_WEEK no exception");
        } catch (IllegalArgumentException e) {
            System.out.println("DAY_OF_WEEK IllegalArgumentException: " + e.getMessage());
        }

        // unsupported fragment
        try {
            DateUtils.getFragmentInDays(Calendar.getInstance(), Calendar.ZONE_OFFSET);
            System.out.println("ZONE_OFFSET no exception");
        } catch (IllegalArgumentException e) {
            System.out.println("ZONE_OFFSET IllegalArgumentException: " + e.getMessage());
        }

        // getFragmentInDays MILLISECOND always 0
        System.out.println("getFragmentInDays MILLISECOND: " + DateUtils.getFragmentInDays(c9, Calendar.MILLISECOND));

        // year too large
        try {
            Calendar big = Calendar.getInstance();
            big.clear();
            big.set(Calendar.YEAR, 280000001);
            DateUtils.truncate(big, Calendar.MONTH);
            System.out.println("big year no exception");
        } catch (ArithmeticException e) {
            System.out.println("big year ArithmeticException: " + e.getMessage());
        }

        // setHours invalid
        try {
            DateUtils.setHours(new java.util.Date(), 24);
            System.out.println("setHours 24 no exception");
        } catch (IllegalArgumentException e) {
            System.out.println("setHours 24 IllegalArgumentException");
        }
    }

    static String fmt(Calendar c) {
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
        sdf.setTimeZone(c.getTimeZone());
        return sdf.format(c.getTime());
    }
}
